// Frozen pre-tournament expectations - the join layer between the bundled locked projection JSON and
// the live players index. PURE + client-safe: this module imports only the committed data bundle and
// player TYPES (erased at build), never the server-only data layer or Supabase, so it is unit-testable
// under bare Node (web/test/locked_pretournament.mjs) and safe to import from a server component.
//
// The bundle web/src/lib/data/locked_pretournament.json is generated by scripts/gen_locked_pretournament.py
// from players/artifacts/player_projections.json (the pre-tournament baseline; the DB has no cond0
// per-player rows). It is a STATIC import: the values here can never be moved by a live re-projection.
import locked from "@/lib/data/locked_pretournament.json";
import type { PlayerIndexRow } from "@/lib/types/players";
import type { EliminationFacts } from "@/lib/data/playerElimination";

/** One locked record: the frozen pre-tournament expected goals / assists for a player. Either metric
 *  may be null (the artifact projected only one). name/nation are carried for display + the fallback join. */
export interface LockedRecord {
  xgPre: number | null;
  xaPre: number | null;
  name: string;
  nation: string;
}

/** The committed bundle shape: provenance _meta plus the two lookup maps. */
export interface LockedBundle {
  _meta: {
    source_artifact: string;
    artifact_version: string | null;
    as_of: string | null;
    label: string;
    generated_by: string;
    player_count: number;
    statsbomb_keyed_count: number;
  };
  byStatsbomb: Record<string, LockedRecord>;
  byNameNation: Record<string, LockedRecord>;
}

/** The frozen bundle, as a static import (NOT derived from any live read). */
export const LOCKED = locked as unknown as LockedBundle;

/** Deterministic token normalization - MUST mirror scripts/gen_locked_pretournament.py norm(): NFD
 *  accent-fold, drop combining diacritical marks (U+0300..U+036F), lowercase, keep only [a-z0-9]. Used
 *  for the name+nation fallback join key so a runtime lookup matches a committed key exactly. Written
 *  as an explicit codepoint filter so the source stays pure ASCII. */
export function normToken(s: string): string {
  const nfd = (s ?? "").normalize("NFD");
  let out = "";
  for (const ch of nfd) {
    const code = ch.codePointAt(0) ?? 0;
    if (code >= 0x0300 && code <= 0x036f) continue; // combining diacritical marks (accents)
    out += ch;
  }
  return out.toLowerCase().replace(/[^a-z0-9]+/g, "");
}

/** The name+nation fallback key, identical to the Python name_nation_key(). */
export function nameNationKey(name: string, nation: string): string {
  return `${normToken(name)}|${normToken(nation)}`;
}

/** Look up a player's frozen record: prefer the exact StatsBomb id, fall back to the normalized
 *  name+nation. Returns null when neither matches - an unmatched player carries NO locked value
 *  (never fabricated, never mis-joined). */
export function lookupLocked(
  bundle: LockedBundle,
  who: { statsbombId: number | null; name: string; nation: string },
): LockedRecord | null {
  if (who.statsbombId != null) {
    const byId = bundle.byStatsbomb[String(who.statsbombId)];
    if (byId) return byId;
  }
  return bundle.byNameNation[nameNationKey(who.name, who.nation)] ?? null;
}

/** One row of the pre-tournament-vs-live comparison surface. */
export interface PreExpectationRow {
  id: string;
  name: string;
  nation: string;
  role: string | null;
  /** Frozen pre-tournament projection (static; a re-projection cannot change it). null when unprojected. */
  xgPre: number | null;
  xaPre: number | null;
  /** The DISPLAYED "now" value. For an ALIVE player this is the LIVE (re-projected) full-tournament
   *  projection. For an ELIMINATED player it is FROZEN to his AS-PLAYED value (accumulated played-match
   *  xG/xA), which a re-projection can never move + which can never rise (he plays no more matches).
   *  null when unavailable (no projection when alive; no played-match xG when eliminated -> DASH). */
  xgLive: number | null;
  xaLive: number | null;
  /** Accumulated actuals so far. */
  goalsActual: number;
  assistsActual: number;
  /** now - pre. For an alive player: live minus frozen (positive = the model now expects MORE). For an
   *  eliminated player: as-played minus the full-tournament projection (greyed in the UI). null when
   *  either side is null. */
  xgDelta: number | null;
  xaDelta: number | null;
  /** True when the player's team is ELIMINATED (positive results proof): the "now" value is frozen. */
  eliminated: boolean;
  /** The short OUT-badge stage label for an eliminated player (e.g. "R16"); null when alive. */
  outStageLabel: string | null;
}

/** The live-index fields the join reads (a structural subset of PlayerIndexRow, so both the real rows
 *  and a hand-built test fixture satisfy it). `team` keys the elimination lookup; `asPlayedXg/asPlayedXa`
 *  are the accumulated played-match xG/xA the freeze collapses an eliminated player's "now" onto. */
type LiveLike = Pick<
  PlayerIndexRow,
  "id" | "name" | "nation" | "team" | "role" | "statsbombId"
  | "expectedGoals" | "expectedAssists" | "actualGoals" | "actualAssists"
  | "asPlayedXg" | "asPlayedXa"
>;

const delta = (now: number | null, pre: number | null): number | null =>
  now != null && pre != null ? now - pre : null;

/** Join the live index rows to the frozen bundle, keeping ONLY players with a locked match that
 *  carries at least one frozen metric, and applying the ELIMINATED-PLAYER FREEZE.
 *
 *  FREEZE: a player whose team is ELIMINATED (present in `eliminations`, keyed by team name / nation)
 *  has his "now" value frozen to his AS-PLAYED value (accumulated played-match xG/xA) instead of the
 *  live re-projection. A knocked-out player plays no more matches, so a correct full-tournament
 *  projection collapses to his played-matches xG; the accumulated actuals never move on a re-run, so
 *  the frozen "now" is byte-identical across all later runs and can never rise. F(F(x)) = F(x): the
 *  function is idempotent (re-applying the freeze reproduces the same as-played value). A team ABSENT
 *  from `eliminations` (unmapped / still alive) keeps the LIVE projection (fail-open).
 *
 *  PURE + deterministic: sorted by the DISPLAYED now-value desc (nulls last), eliminated rows INLINE,
 *  then frozen xG desc, then name. The frozen + as-played values come from static/actual inputs, so no
 *  live re-projection can alter an eliminated row. */
export function buildPreExpectations(
  rows: LiveLike[],
  eliminations: EliminationFacts = new Map(),
  bundle: LockedBundle = LOCKED,
): PreExpectationRow[] {
  const out: PreExpectationRow[] = [];
  for (const r of rows) {
    const rec = lookupLocked(bundle, { statsbombId: r.statsbombId, name: r.name, nation: r.nation });
    if (!rec) continue; // unmatched -> no locked value, excluded from the comparison (never fabricated)
    if (rec.xgPre == null && rec.xaPre == null) continue;

    // ELIMINATION lookup: prefer the WC team, fall back to nation (usually identical). A null/unmapped
    // team is never in the map -> fails open (the live projection stands).
    const teamKey = r.team ?? r.nation;
    const elim = teamKey ? eliminations.get(teamKey) : undefined;
    const eliminated = !!elim;

    // "now" = the LIVE projection when alive; the FROZEN as-played value when eliminated.
    const xgNow = eliminated ? r.asPlayedXg : r.expectedGoals;
    const xaNow = eliminated ? r.asPlayedXa : r.expectedAssists;

    out.push({
      id: r.id,
      name: r.name,
      nation: r.nation,
      role: r.role,
      xgPre: rec.xgPre,
      xaPre: rec.xaPre,
      xgLive: xgNow,
      xaLive: xaNow,
      goalsActual: r.actualGoals,
      assistsActual: r.actualAssists,
      xgDelta: delta(xgNow, rec.xgPre),
      xaDelta: delta(xaNow, rec.xaPre),
      eliminated,
      outStageLabel: elim ? elim.label : null,
    });
  }
  // Sort by the DISPLAYED now-value (frozen for eliminated rows), so a frozen row sits INLINE and only
  // changes rank when a live row genuinely crosses it. Nulls last, then frozen xG, then name.
  out.sort(
    (a, b) =>
      (b.xgLive ?? -Infinity) - (a.xgLive ?? -Infinity) ||
      (b.xgPre ?? -Infinity) - (a.xgPre ?? -Infinity) ||
      a.name.localeCompare(b.name),
  );
  return out;
}
